// expect: exit 3
void deep(int n)
{
    if (n == 0)
        exit(3);
    deep(n - 1);
}
int main(void)
{
    char *p = malloc(1000);
    if (!p || malloc(40000))
        return 1;
    free(p);
    free(0);
    deep(10);
    return 0;
}
